def validate_upstream():
    validate_sha(PROTOCOL, EXPECTED_PROTOCOL_SHA256, "D3 protocol")
    validate_sha(R05D1_LOCK, EXPECTED_R05D1_LOCK_SHA256, "D1 lock")
    validate_sha(R05D2_LOCK, EXPECTED_R05D2_LOCK_SHA256, "D2 lock")
    validate_sha(R05D2_SCRIPT, EXPECTED_R05D2_SCRIPT_SHA256, "D2 script")
    validate_sha(R03_LOCK, EXPECTED_R03_LOCK_SHA256, "R03 lock")
    validate_sha(R03_SCRIPT, EXPECTED_R03_SCRIPT_SHA256, "R03 script")
    validate_sha(PRANET_HELPER, EXPECTED_PRANET_HELPER_SHA256, "PraNet helper")
    validate_sha(DEEPLAB_HELPER, EXPECTED_DEEPLAB_HELPER_SHA256, "DeepLab helper")

    d1 = json.loads(R05D1_LOCK.read_text(encoding="utf-8"))
    d2 = json.loads(R05D2_LOCK.read_text(encoding="utf-8"))
    r03_lock = json.loads(R03_LOCK.read_text(encoding="utf-8"))

    if d1.get("decision") != EXPECTED_R05D1_DECISION:
        raise RuntimeError(f"Unexpected D1 decision: {d1.get('decision')}")
    if int(d1.get("eligible_confirmatory_cases", -1)) != EXPECTED_CASES:
        raise RuntimeError("D1 eligible target count changed.")
    if int(d1.get("exact_overlap_exclusions", -1)) != 0:
        raise RuntimeError("D1 overlap exclusion count changed.")
    if bool(d1.get("target_gt_pixels_decoded", True)):
        raise RuntimeError("D1 reports target GT decoding.")

    if d2.get("decision") != EXPECTED_R05D2_DECISION:
        raise RuntimeError(f"Unexpected D2 decision: {d2.get('decision')}")
    if int(d2.get("target_cases", -1)) != EXPECTED_CASES:
        raise RuntimeError("D2 target count changed.")
    if int(d2.get("model_states", -1)) != EXPECTED_STATES:
        raise RuntimeError("D2 model-state count changed.")
    if int(d2.get("model_case_rows", -1)) != EXPECTED_MODEL_CASES:
        raise RuntimeError("D2 model-case row count changed.")
    if bool(d2.get("target_gt_pixels_decoded", True)):
        raise RuntimeError("D2 reports target GT decoding.")
    if bool(d2.get("target_outcomes_revealed", True)):
        raise RuntimeError("D2 reports target outcome reveal.")
    if bool(d2.get("predictor_fit_or_modified", True)):
        raise RuntimeError("D2 reports predictor modification.")

    # IMPORTANT: only hash the frozen D2 table; never parse probability rows.
    d2_table = artifact_path_from_lock(
        R05D2_DIR,
        d2,
        "target_paot_probabilities",
    )
    validate_sha(d2_table, EXPECTED_D2_TABLE_SHA256, "D2 PAOT table")

    d1_manifest = artifact_path_from_lock(
        R05D1_DIR,
        d1,
        "frozen_confirmatory_manifest",
    )

    if r03_lock.get("decision") != EXPECTED_R03_DECISION:
        raise RuntimeError(f"Unexpected R03 decision: {r03_lock.get('decision')}")

    return d1, d2, r03_lock, d1_manifest, d2_table

def validate_upstream():
    validate_sha(PROTOCOL, EXPECTED_PROTOCOL_SHA256, "Q1-R03 protocol")
    validate_sha(R02_LOCK, EXPECTED_R02_LOCK_SHA256, "Q1-R02 lock")
    r02 = json.loads(R02_LOCK.read_text(encoding="utf-8"))
    if r02.get("decision") != EXPECTED_R02_DECISION:
        raise RuntimeError(
            f"INVALID_Q1_R03_UPSTREAM_PROVENANCE: R02 decision={r02.get('decision')}"
        )

    validate_sha(
        Q1_S00A_LOCK, EXPECTED_Q1_S00A_LOCK_SHA256, "Q1-S00A lock"
    )
    validate_sha(
        S07B_TABLE, EXPECTED_S07B_TABLE_SHA256, "S07-B utility table"
    )
    validate_sha(
        PRANET_HELPER, EXPECTED_PRANET_HELPER_SHA256, "PraNet S03 helper"
    )
    validate_sha(
        PRANET_TRAINING_HELPER,
        EXPECTED_PRANET_TRAINING_HELPER_SHA256,
        "PraNet training helper",
    )
    validate_sha(
        DEEPLAB_HELPER, EXPECTED_DEEPLAB_HELPER_SHA256, "DeepLab S05-C helper"
    )
    validate_sha(
        DEEPLAB_TRAINING_HELPER,
        EXPECTED_DEEPLAB_TRAINING_HELPER_SHA256,
        "DeepLab training helper",
    )

    q1_lock = json.loads(Q1_S00A_LOCK.read_text(encoding="utf-8"))
    feature_art = q1_lock.get("artifacts", {}).get("gradient_probe_features", {})
    feature_expected = feature_art.get("sha256")
    if not feature_expected:
        raise RuntimeError(
            "INVALID_Q1_R03_UPSTREAM_PROVENANCE: Q1-S00A lock lacks feature SHA"
        )
    validate_sha(Q1_S00A_FEATURES, feature_expected, "Q1-S00A B0 table")

    if not DEEPLAB_AUDIT.exists():
        raise FileNotFoundError(DEEPLAB_AUDIT)
    deep_audit = json.loads(DEEPLAB_AUDIT.read_text(encoding="utf-8"))
    deep_table_expected = deep_audit.get("source_training_table_sha256")
    if not deep_table_expected:
        raise RuntimeError(
            "INVALID_Q1_R03_UPSTREAM_PROVENANCE: S05-C audit lacks table SHA"
        )
    validate_sha(DEEPLAB_TABLE, deep_table_expected, "S05-C frozen table")

    panel = []
    for family, mapping in (
        ("PraNet", PRANET_CHECKPOINTS),
        ("DeepLabV3-R50", DEEPLAB_CHECKPOINTS),
        ("SegFormer-B0", SEGFORMER_CHECKPOINTS),
    ):
        for seed, (path, sha) in mapping.items():
            validate_sha(path, sha, f"{family} checkpoint seed {seed}")
            panel.append({
                "model_family": family,
                "seed": seed,
                "model_state_id": f"{family}::{seed}",
                "checkpoint": str(path),
                "checkpoint_sha256": sha,
            })

    if len(panel) != 9 or len({r["checkpoint_sha256"] for r in panel}) != 9:
        raise RuntimeError("INVALID_Q1_R03_PANEL_CHECKPOINT")

    return panel, {
        "protocol_sha256": EXPECTED_PROTOCOL_SHA256,
        "manifest_sha256": EXPECTED_MANIFEST_SHA256,
        "r02_lock_sha256": EXPECTED_R02_LOCK_SHA256,
        "q1_s00a_lock_sha256": EXPECTED_Q1_S00A_LOCK_SHA256,
        "q1_s00a_feature_sha256": feature_expected,
        "s07b_table_sha256": EXPECTED_S07B_TABLE_SHA256,
        "deeplab_table_sha256": deep_table_expected,
    }

def validate_global_rows(rows):
    if len(rows) != EXPECTED_TOTAL_ROWS:
        raise RuntimeError(
            f"INVALID_Q1_R03_CARDINALITY: total={len(rows)} "
            f"expected={EXPECTED_TOTAL_ROWS}"
        )

    states = Counter(r["model_state_id"] for r in rows)
    if len(states) != 9 or any(v != EXPECTED_ROWS_PER_STATE for v in states.values()):
        raise RuntimeError(f"INVALID_Q1_R03_CARDINALITY: states={dict(states)}")

    families = Counter(r["model_family"] for r in rows)
    expected_family = {
        "PraNet": EXPECTED_ROWS_PER_FAMILY,
        "DeepLabV3-R50": EXPECTED_ROWS_PER_FAMILY,
        "SegFormer-B0": EXPECTED_ROWS_PER_FAMILY,
    }
    if dict(families) != expected_family:
        raise RuntimeError(
            f"INVALID_Q1_R03_CARDINALITY: families={dict(families)}"
        )

    global_keys = {
        (
            r["model_state_id"],
            r["sample_id"],
            r["perturbation"],
        )
        for r in rows
    }
    if len(global_keys) != EXPECTED_TOTAL_ROWS:
        raise RuntimeError("INVALID_Q1_R03_CARDINALITY: duplicate global key")

    groups = defaultdict(set)
    for r in rows:
        groups[r["sample_id"]].add(int(r["fold"]))
    if len(groups) != SOURCE_VAL_N:
        raise RuntimeError("INVALID_Q1_R03_GROUP_FOLD: group count")
    if any(len(v) != 1 for v in groups.values()):
        raise RuntimeError("INVALID_Q1_R03_GROUP_FOLD: fold leakage")

    fold_counts = Counter(next(iter(v)) for v in groups.values())
    if dict(sorted(fold_counts.items())) != EXPECTED_FOLD_GROUP_COUNTS:
        raise RuntimeError("INVALID_Q1_R03_GROUP_FOLD: fold counts")

def main():
    args = parse_args()
    if args.self_test:
        self_test()
        return 0
    if args.deeplab_parity_only:
        return run_deeplab_parity_only()
    if args.preflight_only:
        run_preflight()
        return 0
    try:
        run(args)
    except Exception:
        traceback.print_exc()
        raise
    return 0

def patch_r05d3_cardinality(r05d3):
    # Reuse model-specific implementation unchanged, but with PolypGen count.
    r05d3.EXPECTED_CASES = EXPECTED_CASES
    r05d3.EXPECTED_STATES = EXPECTED_STATES
    r05d3.EXPECTED_MODEL_CASES = EXPECTED_MODEL_CASES

    if int(r05d3.MASK_H) != MASK_H or int(r05d3.MASK_W) != MASK_W:
        raise RuntimeError("R05D3 mask resolution changed.")
    if int(r05d3.PACKED_BYTES) != PACKED_BYTES:
        raise RuntimeError("R05D3 packed-mask byte count changed.")
    if str(r05d3.BITORDER) != BITORDER:
        raise RuntimeError("R05D3 packbits bitorder changed.")
    if float(r05d3.TENT_LR) != 1e-3:
        raise RuntimeError("R05D3 TENT lr changed.")
    if float(r05d3.TENT_WEIGHT_DECAY) != 0.0:
        raise RuntimeError("R05D3 TENT weight decay changed.")
    if int(r05d3.TENT_STEPS) != 1:
        raise RuntimeError("R05D3 TENT step count changed.")

    for name in [
        "run_pranet_state",
        "run_deeplab_state",
        "run_segformer_state",
        "pack_mask",
        "unpack_mask",
    ]:
        if not hasattr(r05d3, name):
            raise RuntimeError(f"R05D3 missing required function: {name}")

